import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CD2m2Tvf.js";const p=JSON.parse('{"title":"Feature Inventory & Architecture Traces","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),n={name:"01-features.md"};function o(s,e,c,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="feature-inventory-architecture-traces" tabindex="-1">Feature Inventory &amp; Architecture Traces <a class="header-anchor" href="#feature-inventory-architecture-traces" aria-label="Permalink to &quot;Feature Inventory &amp; Architecture Traces&quot;">​</a></h1><p>This document details the core capabilities of <strong>14-Tracing-Backend</strong>. Every feature includes user behavior, code references, complexity, failure modes, and interview rehearsal scripts.</p><hr><h2 id="f1-opentelemetry-otlp-collector-non-blocking-ingest" tabindex="-1">F1: OpenTelemetry OTLP Collector &amp; Non-blocking Ingest <a class="header-anchor" href="#f1-opentelemetry-otlp-collector-non-blocking-ingest" aria-label="Permalink to &quot;F1: OpenTelemetry OTLP Collector &amp; Non-blocking Ingest&quot;">​</a></h2><h3 id="technical-description" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Accepts OpenTelemetry-compliant trace telemetry over HTTP/JSON and Protobuf. Implements a bounded in-memory buffer with async worker flushing, backpressure rejection (HTTP 429), and strict PII attribute redaction.</p><ul><li><strong>Primary Source</strong>: <code>backend/src/collector/otlp.py</code>, <code>backend/src/collector/queue_buffer.py</code></li><li><strong>Data Models</strong>: <code>backend/src/storage/models.py</code> (<code>SpanRecord</code>, <code>TraceSummary</code>)</li><li><strong>Key Algorithms</strong>: Ring-buffer queue with sliding drop policy when memory threshold exceeds 90%.</li></ul><h3 id="say-it-out-loud" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I built the OpenTelemetry ingestion collector using FastAPI and an asynchronous queue buffer. When microservices emit telemetry, they POST span batches to our OTLP endpoint. Rather than performing synchronous database writes on the request thread, I validate the payload schema, scrub sensitive header and tag attributes using our regex PII filter, and push the batch into a bounded in-memory ring buffer. Background workers drain this buffer using batch inserts into ClickHouse. If downstream storage slows down, the collector applies backpressure and returns a 429 status code with a Retry-After header, preventing out-of-memory crashes.&quot;</p></blockquote><hr><h2 id="f2-tail-based-intelligent-sampling" tabindex="-1">F2: Tail-Based Intelligent Sampling <a class="header-anchor" href="#f2-tail-based-intelligent-sampling" aria-label="Permalink to &quot;F2: Tail-Based Intelligent Sampling&quot;">​</a></h2><h3 id="technical-description-1" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description-1" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Unlike naive head sampling at the API gateway which drops requests before execution finishes, tail sampling buffers spans in an active 30-second window until the entire trace finishes. Traces with errors, status codes $\\ge 400$, or duration $&gt; p99$ latency are retained at 100%, while uniform nominal traffic is downsampled to 1%.</p><ul><li><strong>Primary Source</strong>: <code>backend/src/sampling/tail.py</code>, <code>backend/src/sampling/tail_window.py</code></li><li><strong>Memory Complexity</strong>: $O(B)$ where $B$ is the active trace volume within the 30-second window.</li></ul><h3 id="say-it-out-loud-1" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-1" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;One of the most impactful systems I implemented is our tail-based sampling engine. If you use standard 1% head-based sampling at the gateway, you end up throwing away 99% of your catastrophic failures and latency anomalies because you don&#39;t know the request failed until it finishes. My tail sampler holds spans in an in-memory sliding window for 30 seconds. When the root span closes, the engine inspects the entire trace tree: if any child span recorded an unhandled exception or breached our p99 latency threshold, the trace is promoted for permanent storage. Otherwise, it is probabilistically downsampled. This cut storage footprint by over 75% while maintaining 100% visibility into incident regressions.&quot;</p></blockquote><hr><h2 id="f3-span-directed-acyclic-graph-dag-critical-path-engine" tabindex="-1">F3: Span Directed Acyclic Graph (DAG) &amp; Critical Path Engine <a class="header-anchor" href="#f3-span-directed-acyclic-graph-dag-critical-path-engine" aria-label="Permalink to &quot;F3: Span Directed Acyclic Graph (DAG) &amp; Critical Path Engine&quot;">​</a></h2><h3 id="technical-description-2" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description-2" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Reconstructs the execution tree from un-ordered span records using <code>span_id</code> and <code>parent_span_id</code>. Compensates for inter-host clock skew and executes a topological sort to identify the critical path—the longest path of un-overlapped sequential operations that determined overall latency.</p><ul><li><strong>Primary Source</strong>: <code>backend/src/query/critical_path.py</code>, <code>backend/src/query/trace_lookup.py</code></li><li><strong>Time Complexity</strong>: $O(V + E)$ where $V$ is spans and $E$ is parent-child links.</li></ul><h3 id="say-it-out-loud-2" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-2" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;To help developers pinpoint why a trace took two seconds, I wrote the critical path graph traversal engine. When a trace is opened in the UI, my backend fetches all associated spans and constructs a Directed Acyclic Graph based on parent-child IDs. It normalizes clock drift between microservices and performs a topological traversal to compute the true critical path—the exact chain of blocking operations that directly dictated the total response time. Parallel spans that completed while waiting for a slower query are filtered out. The critical path spans are returned to our React frontend and illuminated in bright red on the waterfall Gantt chart.&quot;</p></blockquote><hr><h2 id="f4-statistical-anomaly-detection-causal-graph" tabindex="-1">F4: Statistical Anomaly Detection &amp; Causal Graph <a class="header-anchor" href="#f4-statistical-anomaly-detection-causal-graph" aria-label="Permalink to &quot;F4: Statistical Anomaly Detection &amp; Causal Graph&quot;">​</a></h2><h3 id="technical-description-3" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description-3" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>A multi-model ML evaluation engine that analyzes span latency distributions, call frequencies, and error spikes across sliding time windows using z-score heuristics and causal dependency graph traversal.</p><ul><li><strong>Primary Source</strong>: <code>ml/latency_anomaly.py</code>, <code>ml/dependency_anomaly.py</code>, <code>ml/root_cause.py</code></li><li><strong>Output</strong>: Ranked anomaly score $(0.0 - 1.0)$ and likely culprit service node.</li></ul><h3 id="say-it-out-loud-3" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-3" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I developed an anomaly detection engine that continuously analyzes incoming telemetry without requiring heavy offline model training. It uses moving-window z-score calculations and service dependency graph traversal. When a service&#39;s latency deviates by more than three standard deviations from its rolling hourly baseline, or if a service suddenly introduces a novel downstream RPC call, an anomaly alert is raised. The root cause module traverses the dependency tree backward from the symptom to the origin, successfully distinguishing between victim services that were merely waiting and the culprit service holding the lock.&quot;</p></blockquote><hr><h2 id="f5-pre-trained-llm-automated-incident-summarizer" tabindex="-1">F5: Pre-trained LLM Automated Incident Summarizer <a class="header-anchor" href="#f5-pre-trained-llm-automated-incident-summarizer" aria-label="Permalink to &quot;F5: Pre-trained LLM Automated Incident Summarizer&quot;">​</a></h2><h3 id="technical-description-4" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description-4" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h3><p>Integrates an external pre-trained LLM API (OpenAI/Anthropic) to ingest serialized anomaly graphs and critical path spans, producing human-readable postmortem summaries and concrete remediation suggestions.</p><ul><li><strong>Primary Source</strong>: <code>ml/llm_engine.py</code>, <code>api/routes/ml.py</code></li><li><strong>Security</strong>: System prompts enforce strict JSON output schemas; all PII and credentials are sanitized before API dispatch.</li></ul><h3 id="say-it-out-loud-4" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud-4" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I integrated a pre-trained LLM into our incident triage workflow to turn raw span trees into plain-English incident postmortems. When an engineer clicks &#39;Summarize Incident&#39;, my backend extracts the critical path spans, error messages, and anomaly scores, scrubs any potential secrets or PII, and sends a strictly structured prompt to the model API. The LLM returns a parsed JSON payload explaining what failed, which downstream resource was bottlenecked, and suggested fixes—like adding a database index or tuning a connection pool. I used zero custom ML model training; everything is grounded in exact telemetry data to prevent hallucinations.&quot;</p></blockquote>',37)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
